        "lingua_originale": "it",
        "titolo_orig": "A Santa Marta cresce la spinta per un futuro senza fossili",
        "testo_it": "A Santa Marta cresce il movimento per la transizione ecologica e l'abbandono dei combustibili fossili.",
        "priorita": "Bassa",
        "id_gruppo": 24,
        "link": "https://ilmanifesto.it/a-santa-marta-cresce-la-spinta-per-un-futuro-senza-fossili",
        "orario": "15:07",
